import {before,after,test} from 'node:test';
import assert from 'node:assert/strict';
import {randomUUID as uid} from 'node:crypto';
import {createServer} from 'node:net';
import {once} from 'node:events';
import {writeFile} from 'node:fs/promises';
import {join} from 'node:path';
import {fifthDatabase} from '../support/h5-018-fifth-isolated.ts';
import {e2e04Fixture,read,write} from '../support/h6-004-fixtures.ts';
import {H4011ModificationAdapter} from '../../src/infrastructure/postgres/h4-modification-adapter.ts';
import {determineCancellation} from '../../src/domain/cancellation-right.ts';
import {civilReference,localDate,zoneEvidence} from '../../src/domain/civil-time.ts';
let h:Awaited<ReturnType<typeof fifthDatabase>>;
const traces:Record<string,unknown>={};
before(async()=>{const server=createServer();server.listen(0,'127.0.0.1');await once(server,'listening');const port=(server.address() as {port:number}).port;await new Promise<void>(r=>server.close(()=>r()));h=await fifthDatabase('h6004_'+uid().replaceAll('-','').slice(0,10),port);});
after(async()=>{if(process.env.H6004_OUTPUT)await writeFile(join(process.env.H6004_OUTPUT,'scenario-readbacks.json'),JSON.stringify(traces,null,2)+'\n');await h?.close();});
for(const scenario of ['A','B'] as const)test(`H6-004 ${scenario} integrated partial cancellation on chain68`,async t=>{
 const f=await e2e04Fixture(h),c=f.c,m=c.m;
 const initial:any=await f.snapshot();traces[scenario]={bookingId:f.bid,serviceId:c.scope.id,initial};
 const record=async(label:string)=>{(traces[scenario] as any)[label]=await f.snapshot();};
 const intact=async()=>{const now:any=await h.booking.read(await h.auth(),read,f.bid);assert.deepEqual(await f.unaffected(),initial.unaffected);assert.deepEqual(now.booking.detail.services.slice(1).map((s:any)=>s.performance),initial.booking.booking.detail.services.slice(1).map((s:any)=>s.performance));assert.notEqual(now.booking.state,'Cancelada');};
 await t.test(`${scenario}01 three services, prior performance and genuine ordinary receipt`,async()=>{assert.equal(f.booking.detail.services.length,3);assert.equal(initial.modification.progress,'Solicitada');assert.equal(initial.refund,null);assert.equal(initial.determination,null);assert.ok(initial.reality);await intact();});
 await t.test(`${scenario}02 provider request and ambiguous response never apply`,async()=>{await m.run(await m.evaluate());await m.run(await f.provider());assert.equal((await m.see())!.progress,'Pendiente de proveedor');await m.run(await f.response('ambiguous'));assert.equal((await m.see())!.progress,'Pendiente de proveedor');await intact();await record('providerPending');});
 await t.test(`${scenario}03 exact provider response, approval guards and no premature application`,async()=>{await m.run(await f.response());assert.equal((await m.see())!.progress,'En evaluación');await assert.rejects(m.run(await m.command('apply',{partIds:[m.partId],approvalRevision:999})));const q=await m.approve(),data:any=structuredClone(q.data);delete data.proofs[m.partId].client;await assert.rejects(m.run(await m.attest({...q,data})));assert.equal((await m.see())!.progress,'En evaluación');await m.run(q);assert.equal((await m.see())!.progress,'Aprobada');assert.notEqual((await h.booking.read(await h.auth(),read,f.bid) as any).booking.detail.services[0].cancelled,true);await record('approvedNotApplied');});
 await t.test(`${scenario}04 scoped cancellation, replay, material conflict, immutable remainder`,async()=>{const q=await m.apply();await m.run(q);const before=await m.see();assert.equal((await m.run(q)).replayed,true);assert.deepEqual(await m.see(),before);await assert.rejects(m.run(await m.attest({...q,reason:'SYNTHETIC altered replay'})));assert.equal((await h.booking.read(await h.auth(),read,f.bid) as any).booking.detail.services[0].cancelled,true);await intact();assert.equal(await f.view(),null);assert.deepEqual(await h.allocations.read(await h.auth(),read,f.payment.paymentId),initial.funds);await record('operationalOnly');});
 if(scenario==='B')await t.test('B05 missing D019 base preserves explicit pending; no refund or obligation effect',async()=>{await c.run(await f.determineRight(true));const v=await c.see();assert.equal(v.computed.status,'pending');assert.equal(v.computed.right,null);assert.ok(v.computed.missing.includes('base:D019'));const obligation=await f.obligation();await assert.rejects(c.run(await f.adjustment()),/DETERMINATION_REQUIRED/);assert.deepEqual(await f.obligation(),obligation);await f.run(await f.request());await assert.rejects(f.run(await f.determine()));assert.equal((await f.view())!.executed,'0.00');await assert.rejects(f.run(await f.authorization()));assert.deepEqual(await h.allocations.read(await h.auth(),read,f.payment.paymentId),initial.funds);await record('economicPending');});
 await t.test(`${scenario}06 explicit attributable200 gives right200, no money`,async()=>{const old=await c.see();const q=await f.determineRight();await c.run(q);const v=await c.see();assert.equal(v.computed.right,'200.00');assert.equal(v.computed.retention,'0.00');assert.equal(v.computed.temporal.daysBefore,3);if(old)assert.deepEqual(v.history.slice(0,old.history.length),old.history);assert.equal((await c.run(q)).replayed,true);assert.deepEqual(await h.allocations.read(await h.auth(),read,f.payment.paymentId),initial.funds);await record('rightDetermined');});
 await t.test(`${scenario}07 approved obligation adjustment reduces only canceled200; gross receipt preserved`,async()=>{const original=(await f.obligation())!;const q=await f.adjustment();await c.run(q);assert.equal((await c.run(q)).replayed,true);const now=(await f.obligation())!;assert.deepEqual(now.original,original.original);assert.equal(now.current.snapshot.parts.find(p=>p.slot==='initial')!.amount,'400.06');assert.equal(now.current.snapshot.parts.find(p=>p.slot==='balance')!.amount,'600.06');assert.deepEqual(await h.allocations.read(await h.auth(),read,f.payment.paymentId),initial.funds);await intact();});
 await t.test(`${scenario}08 Refund determination requires exact right; ordinary authorization denied`,async()=>{if(!await f.view())await f.run(await f.request());await f.run(await f.determine());assert.equal((await f.view())!.right,'200.00');assert.equal((await f.view())!.executed,'0.00');const q=await f.authorization();await assert.rejects(f.run(q));assert.equal((await f.view())!.executed,'0.00');await f.assessRefund();await record('refundDue');});
 await t.test(`${scenario}09 prospective TTE approval authorizes200 without execution`,async()=>{const q=await f.authorization(),a=await f.approveRefund(q);await a.execute();const v=await f.view();assert.equal(v!.executed,'0.00');assert.equal(v!.pendingAuthorized,'200.00');await a.execute();assert.deepEqual(await f.view(),v);await record('refundAuthorized');});
 await t.test(`${scenario}10 actual synthetic output80 retains120 pending and blocks closure`,async()=>{const q=await f.movement('80.00');await f.run(q);const v=await f.view();assert.equal(v!.executed,'80.00');assert.equal(v!.pendingRight,'120.00');assert.equal(v!.pendingAuthorized,'120.00');const snapshot=await f.view();assert.equal((await f.run(q)).replayed,true);assert.deepEqual(await f.view(),snapshot);await f.assessRefund();const closure=await f.closures.view();assert.equal(closure.assessments.economic!.criteria.find(c=>c.id==='refunds')!.result,'pending');await assert.rejects(f.joint.run(await f.joint.command()),/DIMENSION_PENDING/);await record('partial80Pending120');});
 await t.test(`${scenario}11 excessive output and alien root reject without effects`,async()=>{const q=await f.movement('121.00','80.00'),before=await f.view();await assert.rejects(f.run(q));assert.deepEqual(await f.view(),before);const valid=await f.movement('120.00','80.00');await assert.rejects(f.run(await f.attest({...valid,bookingId:uid()})));assert.deepEqual(await f.view(),before);await intact();});
 await t.test(`${scenario}12 complete remaining120, fixed right preserved, no duplicate movement`,async()=>{const q=await f.movement('120.00','80.00');await f.run(q);const v=await f.view();assert.equal(v!.right,'200.00');assert.equal(v!.executed,'200.00');assert.equal(v!.pendingRight,'0.00');assert.equal(v!.pendingAuthorized,'0.00');assert.equal((await f.run(q)).replayed,true);assert.deepEqual(await f.view(),v);await f.assessRefund(true);const end=await f.closures.view();assert.equal(end.assessments.economic!.criteria.find(c=>c.id==='refunds')!.result,'satisfied');assert.equal(end.jointClosure.current,false);await intact();await record('final');});
 await t.test(`${scenario}13 readback preserves original performance and decision history`,async()=>{const end:any=await f.snapshot();assert.deepEqual(end.reality.history,initial.reality.history);assert.ok(end.modification.history.length>=6);assert.ok(end.determination.history.length>=(scenario==='B'?3:2));assert.ok(end.refund.history.length>=5);assert.ok(end.closures.history.length>=3);await intact();});
});
test('H6-004 N01 D020 independent expected civil day boundaries 7/3/2 and whole late day',async()=>{const f=await e2e04Fixture(h),q=await f.c.command();for(const [at,days,right,retention] of [['2026-10-13T23:59:59+02:00',7,'200.00','0.00'],['2026-10-17T00:00:00+02:00',3,'100.00','100.00'],['2026-10-17T23:59:59+02:00',3,'100.00','100.00'],['2026-10-18T00:00:00+02:00',2,'0.00','200.00']] as const){const computed=determineCancellation({...q.facts!,cause:'voluntary',at,base:{kind:'component',amount:'200.00',count:1,start:0,components:[{source:'SYNTHETIC independently fixed200'}]},reference:civilReference({scope:'service',scopeId:f.c.scope.id},localDate('2026-10-20'),zoneEvidence('Europe/Madrid','SYNTHETIC explicitly agreed zone','1'),f.booking.q.versionId,'1')});assert.equal(computed.temporal!.daysBefore,days);assert.equal(computed.right,right);assert.equal(computed.retention,retention);}});
test('H6-004 N02 permission, direct SQL and cross-root protections on actual chain68',async()=>{const f=await e2e04Fixture(h),q=await f.c.m.evaluate(),before=await f.c.m.see();await assert.rejects(h.modifications.apply({} as never,write,q));await assert.rejects(h.modifications.apply(await h.auth(),read,q));await assert.rejects(h.runtime`select * from crm_private.b06_modification_revisions`);await assert.rejects(h.runtime`update crm_private.b06_modifications set admin_scope='wrong'`);await assert.rejects(f.c.m.run(await f.c.m.attest({...q,bookingId:uid()})));assert.deepEqual(await f.c.m.see(),before);});
test('H6-004 N03 application response lost after COMMIT recovers exactly once',async()=>{const f=await e2e04Fixture(h),m=f.c.m;await m.run(await m.evaluate());await m.run(await f.provider());await m.run(await f.response());await m.run(await m.approve());const q=await m.apply();const sql={begin:async(options:any,work:any)=>{await h.runtime.begin(options,work);throw new Error('SYNTHETIC_H6004_LOST_AFTER_COMMIT');}} as unknown as typeof h.runtime;await assert.rejects(new H4011ModificationAdapter(sql,h.f1,h.f2).apply(await h.auth(),write,q));assert.equal((await m.see())!.progress,'Aplicada');const prior=await m.see();assert.equal((await m.run(q)).replayed,true);assert.deepEqual(await m.see(),prior);});
test('H6-004 N04 deferred failure rolls back application and history, authorized retry succeeds',async()=>{const f=await e2e04Fixture(h),m=f.c.m;await m.run(await m.evaluate());await m.run(await f.provider());await m.run(await f.response());await m.run(await m.approve());const q=await m.apply(),before=await f.snapshot();await h.admin.unsafe("create function crm_private.h6004_failure() returns trigger language plpgsql as $$begin raise exception 'SYNTHETIC_H6004_FAIL';end$$");await h.admin.unsafe('create constraint trigger h6004_failure after insert on crm_private.b06_modification_operations deferrable initially deferred for each row execute function crm_private.h6004_failure()');try{await assert.rejects(m.run(q));assert.deepEqual(await f.snapshot(),before);}finally{await h.admin.unsafe('drop trigger h6004_failure on crm_private.b06_modification_operations');await h.admin.unsafe('drop function crm_private.h6004_failure()');}await m.run(q);assert.equal((await m.see())!.progress,'Aplicada');});
